"""Editorial source for CC-02.

Each row is deliberately compact and reviewable.  The renderer expands it into
the five ENTENDA-T1 sections without changing the legal proposition in the row.
Nothing in this file is marked as human-approved.
"""
from __future__ import annotations

ROWS = {
"1": ("Toda pessoa tem aptidão para ser titular de direitos e deveres na esfera civil.", "Essa capacidade de direito acompanha a personalidade. Ela não significa que a pessoa possa praticar sozinha todo ato: idade ou outra causa legal pode exigir representação ou assistência.", "Um recém-nascido pode receber uma doação, embora o representante legal aceite e administre o bem em seu nome.", "Ser titular de um direito é diferente de poder exercê-lo pessoalmente; os arts. 3º e 4º tratam dessa segunda questão.", "capacidade de direito", "aptidão para possuir direitos e assumir deveres civis"),
"2": ("A personalidade civil começa com o nascimento com vida, e a lei protege interesses do concebido antes do parto.", "O nascimento com vida é o marco geral da personalidade, mas o nascituro recebe proteção jurídica desde a concepção em situações reconhecidas pelo sistema.", "Uma herança pode reservar quinhão ao filho já concebido, condicionado ao nascimento com vida.", "O artigo não resolve sozinho todas as discussões sobre o alcance dos direitos do nascituro; a aplicação concreta exige revisão jurídica.", "nascituro", "ser humano já concebido e ainda não nascido"),
"3": ("Quem ainda não completou dezesseis anos necessita de representação para atuar pessoalmente na vida civil.", "Eles têm direitos, mas precisam ser representados para praticar atos jurídicos, porque a lei não reconhece autonomia civil direta nessa faixa etária.", "A venda de um bem pertencente a uma criança de doze anos é formalizada por representante, com as autorizações cabíveis.", "A incapacidade é para o exercício pessoal; não elimina personalidade, patrimônio nem proteção jurídica.", "representação", "atuação de alguém em nome da pessoa incapaz"),
"4": ("A incapacidade relativa alcança quem já completou dezesseis anos mas ainda não chegou aos dezoito, ébrios habituais, dependentes de tóxicos, quem não consegue exprimir vontade por causa transitória ou permanente e os pródigos.", "A pessoa conserva direitos e participa dos atos, mas pode precisar de assistência e de limites definidos judicialmente. A capacidade dos indígenas segue legislação especial.", "Um adolescente de dezessete anos celebra contrato relevante ao lado de seu assistente legal, que complementa sua manifestação de vontade.", "Diagnóstico ou deficiência, isoladamente, não cria incapacidade. É necessário enquadramento em hipótese legal; para adultos, a extensão da curatela depende da situação concreta.", "pródigo", "pessoa que dissipa o próprio patrimônio de modo juridicamente relevante"),
"5": ("A menoridade termina aos dezoito anos, podendo cessar antes nas hipóteses legais de emancipação.", "A emancipação pode decorrer de concessão dos pais ou sentença, casamento, emprego público efetivo, colação de grau superior ou estabelecimento civil, comercial ou emprego que dê economia própria ao menor com dezesseis anos completos.", "Pais formalizam emancipação do filho de dezessete anos por instrumento público, sem necessidade de homologação judicial.", "Emancipação civil não altera por si só limites etários de outras áreas, como regras penais ou administrativas.", "emancipação", "antecipação legal da capacidade civil plena do menor"),
"6": ("A morte encerra a existência jurídica individual; em situações previstas, ela também pode ser reconhecida por presunção legal.", "A morte encerra a personalidade e abre efeitos sucessórios e familiares; a presunção depende das hipóteses e procedimentos legais sobre ausência ou perigo de vida.", "Comprovado o óbito, o patrimônio do falecido passa ao regime sucessório.", "O desaparecimento isolado não equivale por si só a morte; deve-se verificar qual modalidade legal de declaração é cabível.", "morte presumida", "reconhecimento jurídico da morte sem prova física direta do óbito"),
"7": ("Pode haver morte presumida sem processo de ausência diante de perigo extremo de vida ou de desaparecimento em campanha ou cativeiro por dois anos após o fim da guerra.", "A declaração somente é pedida depois de esgotadas buscas e averiguações, e a sentença judicial fixa a data provável do falecimento.", "Após desastre com buscas esgotadas e fortes indícios de óbito, familiares pedem ao juiz a declaração.", "As duas hipóteses são excepcionais; a segunda contém prazo próprio contado do término da guerra.", "morte presumida", "reconhecimento judicial da morte sem comprovação direta do óbito"),
"8": ("Se duas ou mais pessoas morrem na mesma ocasião e não se sabe a ordem, presume-se que faleceram simultaneamente.", "A comoriência impede que uma seja considerada herdeira da outra quando não há prova de sobrevivência, alterando a sequência das transmissões patrimoniais.", "Cônjuges morrem no mesmo acidente sem prova de quem sobreviveu; as sucessões são calculadas sem transmissão entre eles.", "A presunção cede diante de prova confiável da ordem das mortes.", "comoriência", "presunção de mortes simultâneas quando a ordem é desconhecida"),
"9": ("Devem ser registrados nascimento, casamento, óbito, emancipação, interdição e sentenças que declarem ausência ou morte presumida.", "O registro dá publicidade, autenticidade e segurança ao estado civil, permitindo que terceiros e autoridades conheçam situações juridicamente relevantes.", "A sentença que declara ausência é levada ao registro público competente.", "A lista do Código Civil convive com os procedimentos e demais atos previstos na legislação de registros públicos.", "registro público", "assento oficial destinado a dar publicidade a fatos jurídicos"),
"10": ("Devem ser averbadas decisões sobre nulidade ou anulação do casamento, divórcio, separação, restabelecimento conjugal e atos que reconheçam filiação.", "A averbação atualiza um assento já existente para que ele reflita mudanças juridicamente reconhecidas; o antigo inciso sobre adoção está revogado.", "Depois do divórcio, a informação é acrescentada ao registro do casamento.", "O artigo não contém hoje uma regra vigente sobre adoção; essa matéria segue a legislação registral e especial aplicável.", "averbação", "anotação que atualiza ou complementa um registro anterior"),
"11": ("Salvo exceções previstas em lei, direitos da personalidade são intransmissíveis e irrenunciáveis, e seu exercício não pode sofrer limitação voluntária.", "A pessoa não pode vender ou abandonar atributos essenciais como nome, integridade e privacidade. Consentimentos específicos só valem dentro das exceções legais e de limites de finalidade, duração e dignidade.", "Um contrato não pode retirar por tempo indefinido todo controle de alguém sobre o uso de sua imagem.", "A regra não impede toda autorização pontual, mas veda transformar atributo essencial da pessoa em renúncia ou transferência irrestrita.", "irrenunciável", "direito que não pode ser abandonado de modo definitivo"),
"12": ("Ameaças e ofensas aos direitos da personalidade admitem medidas para cessação e reparação, inclusive por familiares legitimados após a morte.", "A tutela inibitória pode impedir ou cessar a ofensa; a reparatória busca compensar o dano, sem excluir outras sanções legais.", "Familiares pedem retirada de publicação que viola gravemente a memória do falecido.", "Após a morte, podem agir o cônjuge sobrevivente, parentes em linha reta e colaterais até o quarto grau.", "tutela inibitória", "proteção judicial destinada a impedir ou fazer cessar uma conduta ilícita"),
"13": ("A disposição do próprio corpo que cause diminuição permanente ou contrarie bons costumes é vedada, salvo exigência médica, e transplantes seguem lei especial.", "A autonomia corporal existe, mas encontra limites de integridade, necessidade terapêutica e disciplina específica.", "Uma intervenção com perda permanente de função é avaliada à luz de indicação médica e normas sanitárias.", "Questões médicas e bioéticas não devem ser decididas apenas por este artigo; exigem legislação especial e consentimento válido.", "disposição do corpo", "decisão sobre intervenção, uso ou destinação do próprio corpo"),
"14": ("É válida a disposição gratuita do corpo, total ou parcial, para depois da morte, com finalidade científica ou altruística, e pode ser revogada.", "A pessoa pode manifestar essa vontade sem transformar o corpo em objeto de comércio e conserva a possibilidade de desistir.", "Alguém registra desejo de doar o corpo para ensino e posteriormente revoga a manifestação.", "A execução depende também das regras sanitárias, de transplantes e de manifestação familiar aplicáveis.", "altruístico", "orientado ao benefício de outras pessoas sem vantagem econômica"),
"15": ("Ninguém pode ser obrigado a tratamento médico ou cirurgia com risco de vida.", "A regra protege autonomia e consentimento informado diante de intervenção grave, exigindo diálogo claro sobre riscos e alternativas.", "Paciente consciente recusa procedimento de alto risco após receber explicações médicas adequadas.", "Emergência, incapacidade, dever profissional e normas especiais podem tornar o caso complexo; a conclusão exige avaliação jurídica e clínica.", "consentimento informado", "decisão livre tomada após compreensão suficiente de riscos e alternativas"),
"16": ("Toda pessoa tem direito ao nome, compreendidos prenome e sobrenome.", "O nome individualiza a pessoa na família e na sociedade e integra os direitos da personalidade.", "Uma pessoa pode impedir que documentos oficiais omitam indevidamente seu sobrenome.", "Alteração e registro do nome obedecem também à legislação de registros públicos.", "prenome", "parte do nome que identifica individualmente a pessoa"),
"17": ("O nome não pode ser usado por outra pessoa em publicação ou representação que exponha seu titular ao desprezo público.", "A proteção alcança uso indevido capaz de atingir reputação e dignidade, mesmo sem intenção difamatória expressa.", "Uma campanha satírica não pode associar pessoa identificada a conduta degradante sem base legítima.", "Crítica, informação e liberdade de expressão também importam; a ponderação depende do contexto.", "desprezo público", "rebaixamento da consideração social atribuída à pessoa"),
"18": ("O nome alheio não pode ser utilizado em propaganda comercial sem autorização.", "A exploração publicitária da identidade depende de consentimento, pois pode sugerir apoio ou associação inexistente.", "Uma loja não pode usar o nome de artista em anúncio para atrair clientes sem permissão.", "Uso informativo ou referência não comercial tem análise diferente da propaganda.", "propaganda comercial", "comunicação destinada a promover produto, serviço ou atividade econômica"),
"19": ("O pseudônimo adotado para atividade lícita recebe proteção semelhante à do nome.", "A identidade pública construída sob nome artístico ou literário pode ser defendida contra apropriação e uso lesivo.", "Um escritor impede terceiro de publicar obra enganosa sob seu pseudônimo conhecido.", "A proteção pressupõe uso lícito e não autoriza fraude sobre a identidade civil.", "pseudônimo", "nome escolhido para identificar alguém em determinada atividade"),
"20": ("A pessoa pode pedir proibição e indenização pelo uso de escritos, palavras ou imagem que atinja honra, boa fama ou respeitabilidade, ou tenha finalidade comercial.", "Autorização afasta a proibição em regra. O próprio artigo ressalva usos necessários à administração da justiça ou à ordem pública; para morto ou ausente, cônjuge, ascendentes e descendentes podem requerer proteção.", "Uma loja usa a fotografia de cliente para anunciar produto sem consentimento; a pessoa pede retirada da campanha e reparação.", "Biografias, imprensa e obras de interesse público envolvem liberdade de expressão e controle constitucional indicado na fonte oficial; não se resolvem apenas pela leitura literal.", "respeitabilidade", "consideração social ligada à dignidade e à reputação da pessoa"),
"21": ("A vida privada é inviolável, e o juiz pode adotar providências para impedir ou fazer cessar sua violação.", "A norma oferece proteção ampla contra intromissões indevidas e permite medidas adequadas ao risco concreto.", "Uma pessoa pede bloqueio da divulgação de dados íntimos obtidos sem autorização.", "A privacidade admite ponderação e deve ser harmonizada com deveres legais e liberdades igualmente protegidas.", "vida privada", "esfera pessoal que não deve ser exposta ou invadida sem fundamento legítimo"),
"22": ("Sem notícias da pessoa desaparecida e sem representante apto para administrar seus bens, o juiz declara a ausência e nomeia curador a pedido de interessado ou do Ministério Público.", "A providência protege bens e relações do desaparecido enquanto não se sabe se voltará.", "Empresário some sem procurador e o Ministério Público requer curadoria para proteger o patrimônio.", "A ausência não equivale desde logo a morte e segue etapas próprias.", "curador", "pessoa designada para administrar e proteger interesses de outra"),
"23": ("Também cabe declaração de ausência quando o mandatário não quer, não pode continuar ou possui poderes insuficientes.", "A existência formal de procurador não impede proteção judicial se a representação deixou de funcionar adequadamente.", "O procurador renuncia e não há quem possa pagar obrigações urgentes do desaparecido.", "É preciso demonstrar a insuficiência real da representação, não mera conveniência.", "mandatário", "pessoa que recebeu poderes para agir em nome de outra"),
"24": ("O juiz define os poderes e as obrigações do curador conforme as circunstâncias e aplica, quando compatíveis, as regras relativas a tutores e curadores.", "A administração é controlada e moldada à necessidade do patrimônio do ausente; este artigo não estabelece a ordem de preferência para a nomeação.", "Ao nomear curador, o juiz delimita quais atos de conservação e administração poderão ser praticados.", "A preferência entre possíveis curadores pertence ao artigo seguinte e não deve ser atribuída a este dispositivo.", "curadoria", "encargo judicial de proteção e administração de interesses"),
"25": ("O cônjuge não separado judicialmente nem de fato por mais de dois anos tem preferência; depois vêm pais e descendentes, e, na falta deles, o juiz escolhe o curador.", "Entre descendentes, os mais próximos precedem os remotos, desde que não exista impedimento para exercer o cargo.", "Sem cônjuge apto, a mãe do ausente assume a curadoria antes de um filho, se não houver impedimento.", "A separação de fato superior a dois anos afasta a preferência do cônjuge, e a nomeação continua sujeita ao controle judicial.", "ordem de preferência", "sequência legal usada para escolher quem assume o encargo"),
"26": ("Interessados podem pedir a sucessão provisória um ano após a arrecadação dos bens ou, se havia representante ou procurador, depois de três anos.", "A lei posterga a entrega provisória do patrimônio para permitir retorno ou notícias, com prazo maior quando existia representação.", "Três anos depois do marco aplicável ao desaparecido que deixou procurador, herdeiro pede abertura da fase sucessória.", "O prazo de um ano parte da arrecadação; o caso com representante possui o período especial de três anos.", "sucessão provisória", "entrega temporária e condicionada do patrimônio do ausente"),
"27": ("A lei define quem pode requerer a sucessão provisória: cônjuge não separado, herdeiros, titulares de direitos dependentes da morte e credores vencidos.", "O pedido é reservado a pessoas com vínculo jurídico direto e interesse atual na situação patrimonial.", "Credor cuja dívida venceu pede a abertura para buscar satisfação no patrimônio arrecadado.", "Cada requerente deve provar a condição indicada no artigo.", "interessado", "pessoa cuja esfera jurídica pode ser afetada pela decisão"),
"28": ("A sentença de sucessão provisória produz efeitos cento e oitenta dias após a publicação; depois do trânsito em julgado, já se abrem testamento, inventário e partilha.", "O intervalo cria cautela adicional sem impedir atos preparatórios, e os parágrafos disciplinam iniciativa do Ministério Público e arrecadação se ninguém promover inventário.", "O juiz abre o testamento após o trânsito, enquanto a eficácia sucessória aguarda o prazo contado da publicação.", "Publicação, trânsito em julgado e prazo de trinta dias para comparecimento de interessado são marcos diferentes.", "trânsito em julgado", "momento em que a decisão não admite recurso ordinário"),
"29": ("Antes da partilha, o juiz pode converter bens móveis sujeitos a deterioração ou extravio em imóveis ou títulos garantidos pela União.", "A medida preserva o valor do patrimônio do ausente e depende de juízo de conveniência, não de escolha livre dos sucessores.", "Mercadoria perecível é vendida por ordem judicial e o valor é aplicado em título garantido pela União.", "A hipótese exige risco de deterioração ou extravio; simples preferência por outro investimento não basta.", "deterioração", "perda física ou econômica do valor de um bem"),
"30": ("Para receber a posse provisória, o herdeiro oferece penhor ou hipoteca equivalente ao seu quinhão; ascendentes, descendentes e cônjuge provados como herdeiros são dispensados.", "Quem tem direito, mas não presta a garantia exigida, fica fora da posse; seu quinhão permanece com o curador ou com herdeiro designado pelo juiz que garanta a restituição.", "Herdeiro colateral constitui hipoteca equivalente ao quinhão antes de entrar na posse.", "A dispensa é específica dos familiares enumerados e depende de prova da qualidade de herdeiro.", "quinhão", "parcela do patrimônio atribuída a determinado sucessor"),
"31": ("Imóveis do ausente só podem ser vendidos ou hipotecados por ordem judicial para evitar ruína, salvo desapropriação.", "Os sucessores provisórios administram, mas não dispõem livremente do patrimônio imobiliário.", "Prédio em grave risco estrutural é alienado após autorização judicial para preservar valor.", "Necessidade econômica comum não basta; a hipótese legal precisa ser demonstrada.", "alienação", "transferência da propriedade de um bem"),
"32": ("Empossados, os sucessores provisórios representam o ausente em ações ativas e passivas.", "Eles assumem posição processual para defender direitos e responder por obrigações ligadas ao patrimônio administrado.", "Sucessor prossegue em ação de cobrança que o desaparecido havia iniciado.", "A representação é funcional e temporária, não transforma o sucessor em titular definitivo.", "representação processual", "atuação em juízo na defesa de interesses de outra pessoa"),
"33": ("Descendentes, ascendentes e cônjuge aproveitam integralmente frutos dos bens; outros sucessores capitalizam metade e prestam contas, com consequências para retorno injustificado.", "O artigo diferencia familiares próximos e demais sucessores na renda produzida durante a ausência.", "Irmão em posse provisória deposita metade dos aluguéis e apresenta contas anuais.", "A distribuição e eventual perda de frutos dependem da categoria do sucessor e da justificativa do ausente.", "frutos", "rendimentos periódicos produzidos por um bem sem consumir sua substância"),
"34": ("Excluído da posse por falta de garantia pode pedir metade dos rendimentos que caberiam ao seu quinhão se provar falta de meios.", "A regra evita desamparo completo do sucessor economicamente incapaz de prestar caução.", "Herdeiro sem patrimônio demonstra necessidade e recebe parcela dos rendimentos sob controle judicial.", "O benefício não entrega a posse e exige prova suficiente da impossibilidade econômica.", "quinhão", "parte ideal do patrimônio atribuída a cada sucessor"),
"35": ("Comprovada durante a posse provisória a data exata da morte, considera-se aberta naquele momento a sucessão em favor de quem então era herdeiro.", "A confirmação substitui a data presumida e pode exigir recálculo da transmissão conforme as pessoas com vocação hereditária no óbito real.", "Documento comprova que o ausente morreu antes da posse provisória e a partilha é ajustada aos herdeiros daquela data.", "O artigo trata da prova da morte e não do retorno com vida, matéria disciplinada pelo artigo seguinte.", "abertura da sucessão", "momento jurídico em que a herança se transmite aos herdeiros"),
"36": ("Se o ausente aparecer ou sua existência for provada após a posse provisória, cessam imediatamente as vantagens dos sucessores, que conservam os bens até entrega segura.", "A sucessão provisória recua diante da prova de vida, restabelecendo o titular e impondo medidas de conservação até a restituição.", "Desaparecido retorna e os sucessores protegem o patrimônio enquanto organizam sua entrega.", "O artigo trata do retorno ou prova de vida, e não da confirmação da data da morte.", "restituição", "devolução do bem ou posição jurídica ao titular"),
"37": ("Dez anos após o trânsito da sentença provisória, interessados podem pedir sucessão definitiva e levantamento das garantias.", "O longo período reduz a reversibilidade e consolida a posição dos sucessores, sem apagar integralmente efeitos de eventual retorno.", "Herdeiros requerem conversão da posse após completar o prazo contado da decisão.", "O termo inicial é a sentença indicada no artigo, não qualquer notícia de desaparecimento.", "levantamento da caução", "liberação da garantia antes exigida"),
"38": ("A sucessão definitiva pode ser requerida se o ausente tiver oitenta anos e as últimas notícias forem de cinco anos atrás.", "Idade avançada somada ao silêncio prolongado permite abreviar a consolidação sucessória.", "Pessoa de oitenta e três anos está sem notícias há seis anos e seus herdeiros apresentam o pedido.", "Idade e prazo devem coexistir e ser provados documentalmente.", "últimas notícias", "marco temporal da informação confiável mais recente sobre a pessoa"),
"39": ("Se o ausente, descendente ou ascendente regressar nos dez anos posteriores à sucessão definitiva, recebe apenas bens existentes, substitutos ou preços ainda identificáveis.", "O retorno tardio não recompõe integralmente o acervo; terminado o período sem retorno nem promoção sucessória, os bens arrecadados passam ao ente público indicado no artigo.", "Ausente volta e recebe o imóvel remanescente, sem exigir bem já alienado além do substituto ou preço previsto na regra.", "O texto não inclui todo herdeiro necessário: menciona especificamente o ausente, seus descendentes e seus ascendentes.", "sub-rogação", "substituição de um bem por outro que assume sua posição jurídica"),
"40": ("A lei separa as pessoas jurídicas em categorias públicas, nacionais ou internacionais, e privadas.", "A classificação define regime, criação, responsabilidade e regras aplicáveis à entidade.", "Um município e uma associação possuem personalidade jurídica, mas seguem regimes distintos.", "O rótulo depende da natureza legal da entidade, não apenas de sua atividade.", "pessoa jurídica", "organização reconhecida como sujeito autônomo de direitos e deveres"),
"41": ("O artigo enumera pessoas jurídicas de direito público interno e admite outras criadas por lei.", "União, entes federativos, municípios, autarquias e entidades públicas legalmente qualificadas integram essa categoria.", "Uma autarquia celebra contrato em nome próprio sob regime público.", "Entidade estatal com estrutura privada pode exigir classificação mais cuidadosa.", "autarquia", "entidade pública criada por lei para desempenhar função administrativa própria"),
"42": ("Estados estrangeiros e pessoas regidas pelo direito internacional público são pessoas jurídicas externas.", "A categoria abrange sujeitos internacionais e separa seu regime daquele das entidades públicas brasileiras.", "Um Estado estrangeiro adquire imóvel e figura como titular perante o direito brasileiro.", "Imunidades e relações internacionais dependem de normas além do Código Civil.", "direito internacional público", "conjunto de regras aplicáveis às relações entre sujeitos internacionais"),
"43": ("Pessoas jurídicas de direito público interno respondem civilmente pelos danos causados por seus agentes, preservado regresso contra o culpado.", "A vítima pode buscar reparação da entidade pública; depois, a entidade pode cobrar do agente quando houver dolo ou culpa.", "Servidor causa dano durante o serviço e o lesado pede indenização ao ente público.", "Nexo causal, excludentes e regime constitucional precisam ser examinados no caso concreto.", "direito de regresso", "pretensão de recuperar de responsável o valor pago a terceiro"),
"44": ("São pessoas jurídicas privadas associações, sociedades, fundações, organizações religiosas, partidos políticos e empreendimentos de economia solidária.", "Organizações religiosas têm liberdade de criação e funcionamento; partidos seguem lei específica. As regras de associações aplicam-se subsidiariamente aos empreendimentos solidários e às sociedades referidas pelo § 2º.", "Um grupo cultural sem finalidade econômica registra associação; uma cooperativa popular pode precisar verificar se se enquadra no regime especial de economia solidária.", "O inciso VII e o § 2º mudaram em 2024. Classificar a entidade corretamente é essencial, pois cada espécie possui constituição e regime próprios.", "subsidiariamente", "de forma complementar, para preencher lacuna sem substituir a disciplina principal"),
"45": ("A pessoa jurídica privada começa com o registro do ato constitutivo, precedido de autorização quando exigida; alterações posteriores também são averbadas.", "Antes do registro, a organização não possui a personalidade autônoma pretendida. O direito de anular sua constituição por defeito decai em três anos contados da publicação da inscrição.", "Sociedade passa a existir juridicamente após arquivar seu contrato no registro competente.", "O prazo de três anos trata do defeito do ato constitutivo e começa na publicação da inscrição, não na descoberta do problema.", "ato constitutivo", "documento que cria e organiza a pessoa jurídica"),
"46": ("O registro declara denominação, fins, sede, duração, fundo social quando houver, fundadores e diretores, administração, representação, reforma, responsabilidade dos membros, extinção e destino patrimonial.", "Essas informações permitem identificar estrutura, representação e limites da entidade perante terceiros.", "Estatuto informa quem representa a associação, se os associados respondem subsidiariamente e para onde irá o patrimônio na extinção.", "Fundo social eventual não se confunde com declaração genérica de todo o patrimônio; legislação especial pode exigir outros dados.", "denominação", "nome oficial sob o qual a pessoa jurídica atua"),
"47": ("Atos dos administradores obrigam a pessoa jurídica quando praticados dentro dos poderes definidos no ato constitutivo.", "A entidade responde pela atuação regular de seus órgãos, enquanto excesso de poderes pode gerar consequências distintas.", "Diretor autorizado assina contrato e vincula a entidade.", "Terceiros devem considerar registro, boa-fé e regras específicas sobre representação.", "poderes de administração", "limites de atuação conferidos ao gestor da entidade"),
"48": ("Na administração coletiva, decide a maioria dos votos dos presentes, salvo regra constitutiva diversa. A anulação de certas decisões decai em três anos.", "O prazo alcança deliberação que viole lei ou estatuto ou esteja viciada por erro, dolo, simulação ou fraude.", "Conselho aprova decisão por maioria; comprovada fraude na votação, interessado pede anulação dentro de três anos.", "Maioria, quórum e prazo não são a mesma coisa: o ato constitutivo pode disciplinar os dois primeiros, mas os vícios e a decadência vêm da lei.", "deliberação", "decisão formal tomada por órgão coletivo"),
"48-A": ("As pessoas jurídicas privadas podem realizar assembleias gerais por meios eletrônicos, respeitados participação e manifestação dos integrantes.", "A reunião remota tem validade semelhante à presencial quando preserva direitos políticos e procedimentos aplicáveis.", "Associação convoca assembleia por plataforma que identifica participantes e registra votos.", "Tecnologia utilizada deve permitir acesso, segurança e prova da manifestação; regras especiais continuam válidas.", "assembleia eletrônica", "reunião deliberativa realizada por recursos digitais"),
"49": ("Se faltar administração, o juiz pode nomear administrador provisório a pedido de interessado.", "A intervenção evita paralisação da pessoa jurídica e dura até recomposição regular de sua gestão.", "Falecem os únicos administradores e associado pede nomeação temporária para pagar despesas urgentes.", "A medida é judicial, excepcional e limitada à necessidade demonstrada.", "administrador provisório", "gestor temporário nomeado para suprir ausência da administração regular"),
"49-A": ("A pessoa jurídica não se confunde com sócios, associados, instituidores ou administradores, e a autonomia patrimonial é instrumento lícito de alocação de riscos.", "Bens e dívidas pertencem, em regra, à própria entidade, permitindo atividade organizada sem mistura automática com patrimônios pessoais.", "Dívida contratual da sociedade não é cobrada do sócio apenas porque ele participa do capital.", "A separação não protege fraude ou abuso; hipóteses legais de responsabilização permanecem.", "autonomia patrimonial", "separação entre patrimônio da entidade e patrimônio de seus integrantes"),
"50": ("Havendo abuso por desvio de finalidade ou confusão patrimonial, o juiz pode estender obrigações da pessoa jurídica a bens de administradores ou sócios beneficiados direta ou indiretamente.", "Desvio envolve propósito de lesar credores ou praticar ilícitos. Confusão aparece em pagamentos repetidos de obrigações alheias, transferências sem contraprestação efetiva ou outros atos que eliminem a separação patrimonial. A regra também admite o caminho inverso.", "A empresa paga repetidamente despesas pessoais do sócio; provado o benefício e o abuso, o credor pede que a obrigação alcance seus bens.", "Inadimplência, grupo econômico ou mudança regular da atividade, isoladamente, não bastam. A medida é pontual, depende de requerimento e não extingue a entidade.", "desconsideração", "afastamento excepcional da separação patrimonial para determinada obrigação"),
"51": ("A pessoa jurídica subsiste para fins de liquidação após dissolução ou cassação, até conclusão e cancelamento do registro.", "Encerrar atividades não apaga imediatamente direitos e dívidas; primeiro é necessário realizar ativos, pagar obrigações e destinar saldo.", "Sociedade dissolvida continua cobrando créditos e pagando credores durante a liquidação.", "Dissolução, liquidação e extinção são etapas diferentes e sujeitas ao regime próprio da entidade.", "liquidação", "fase de apuração de ativos, pagamento de dívidas e encerramento patrimonial"),
"52": ("A proteção dos direitos da personalidade aplica-se às pessoas jurídicas no que for compatível.", "Entidades podem defender nome, reputação, identidade e outros atributos adequados à sua natureza, sem equiparação integral à pessoa humana.", "Empresa reage a uso enganoso de sua marca nominal que prejudica sua reputação.", "A compatibilidade precisa ser verificada direito por direito, porque uma entidade não possui corpo, vida familiar ou intimidade humana.", "compatibilidade", "adequação de uma regra à natureza do sujeito a que será aplicada"),
"53": ("Associações resultam da união de pessoas para fins não econômicos e não criam, por si, obrigações recíprocas entre associados.", "O objetivo institucional não é distribuir lucro, e o vínculo associativo segue o estatuto em vez de relação contratual automática entre membros.", "Moradores criam associação cultural para manter biblioteca comunitária.", "A associação pode ter receitas e atividades econômicas instrumentais, desde que não distribua resultado como finalidade.", "fim não econômico", "objetivo institucional sem distribuição de resultado entre membros"),
"54": ("O estatuto da associação deve conter elementos obrigatórios sobre finalidade, membros, recursos, órgãos, alteração, dissolução, contas e gestão.", "A falta de requisito essencial pode tornar o estatuto inválido e comprometer registro ou governança.", "Estatuto define admissão e exclusão, fontes de receita e forma de aprovar contas.", "Modelos genéricos devem ser adaptados à atividade e à legislação especial aplicável.", "estatuto", "conjunto de regras internas que organiza a associação"),
"55": ("Associados devem ter direitos iguais, embora o estatuto possa criar categorias associativas com vantagens especiais.", "A igualdade é a regra, mas diferenças objetivas de categoria podem ser previstas de modo transparente e legítimo.", "Estatuto concede benefício honorífico a fundadores sem retirar direitos essenciais dos demais.", "Distinções arbitrárias ou contrárias à finalidade podem ser questionadas.", "categoria associativa", "classe de membros definida pelo estatuto segundo critérios determinados"),
"56": ("A qualidade de associado não se transfere, salvo previsão estatutária; adquirir quota patrimonial, por si, não torna alguém associado.", "O vínculo costuma ser pessoal e depende das regras de ingresso da entidade.", "Comprador de título patrimonial segue o procedimento de admissão previsto no estatuto.", "Transferência patrimonial e ingresso no quadro social são questões distintas.", "intransmissível", "posição que não passa de uma pessoa para outra sem fundamento próprio"),
"57": ("A exclusão de associado exige justa causa, procedimento estatutário e garantia de defesa e recurso.", "A entidade pode proteger sua finalidade, mas precisa oferecer processo interno minimamente justo.", "Associado acusado de falta grave recebe ciência, apresenta defesa e recorre ao órgão competente.", "A gravidade da causa e a regularidade do procedimento devem ser documentadas.", "justa causa", "motivo relevante e comprovável que legitima a exclusão"),
"58": ("Nenhum associado pode ser impedido de exercer direito ou função legitimamente conferidos, salvo hipóteses legais ou estatutárias.", "A administração não pode retirar direitos de forma improvisada; restrições precisam de fundamento previamente reconhecido.", "Diretoria não suspende voto de membro adimplente sem regra que autorize a medida.", "O próprio estatuto pode estabelecer requisitos válidos para determinados direitos.", "direito legitimamente conferido", "faculdade atribuída de modo válido pela lei ou pelo estatuto"),
"59": ("É competência privativa da assembleia destituir administradores e alterar o estatuto, observando convocação e quórum estatutários.", "Essas matérias estruturais não podem ser transferidas a órgão menor e exigem deliberação dos associados em assembleia convocada para esse fim.", "Mudança da finalidade institucional é votada em assembleia especialmente convocada.", "A redação vigente remete o quórum ao estatuto; convocação defeituosa pode invalidar a decisão.", "competência privativa", "poder decisório reservado a determinado órgão"),
"60": ("A convocação dos órgãos deliberativos segue o estatuto, e um quinto dos associados pode promovê-la.", "A minoria qualificada possui instrumento para provocar deliberação quando a administração não convoca.", "Vinte de cem associados convocam assembleia nos termos estatutários.", "Devem ser respeitados forma, antecedência, pauta e demais garantias de participação.", "convocação", "ato formal que chama os membros para reunião deliberativa"),
"61": ("Dissolvida a associação, o patrimônio líquido restante vai à entidade não econômica indicada no estatuto ou escolhida pelos associados, segundo a ordem legal.", "Estatuto ou deliberação pode antes restituir aos associados o valor atualizado das contribuições patrimoniais. Sem instituição adequada no local, o saldo vai à Fazenda competente.", "Após pagar dívidas e restituir contribuição atualizada autorizada, associação transfere o saldo a instituição de finalidade semelhante.", "A Fazenda do Estado, Distrito Federal ou União é destino subsidiário, usado quando não existe instituição nas condições legais.", "patrimônio remanescente", "saldo que resta depois de encerradas as obrigações da entidade"),
"62": ("A fundação nasce de escritura pública ou testamento, com bens livres destinados a finalidade admitida e eventual modo de administração.", "As finalidades vigentes abrangem assistência social; cultura e patrimônio; educação; saúde; segurança alimentar; meio ambiente e sustentabilidade; pesquisa e tecnologia; ética, cidadania, democracia e direitos humanos; e atividades religiosas.", "Pessoa destina imóvel e recursos por testamento para fundação de educação e cultura.", "O inciso X foi vetado; finalidade, suficiência patrimonial, forma do ato e fiscalização exigem análise técnica.", "dotação", "separação de bens destinados permanentemente a uma finalidade fundacional"),
"63": ("Se houver insuficiência patrimonial para constituir a fundação, os bens irão para outra de finalidade igual ou semelhante, salvo disposição diversa do instituidor.", "A regra evita estrutura inviável e procura preservar a intenção social da doação.", "Capital deixado não sustenta a nova entidade e é transferido a fundação educacional já existente.", "A vontade expressa do instituidor pode estabelecer solução válida diferente.", "insuficiência patrimonial", "falta de recursos adequados para cumprir a finalidade prevista"),
"64": ("Na fundação constituída entre vivos, o instituidor deve efetivar a transferência dos bens ou direitos reais destinados; se omitir o ato, haverá registro por mandado judicial.", "A dotação precisa tornar-se patrimônio efetivo da fundação. A consequência judicial substitui a transferência omitida, desde que o ato e os bens estejam validamente definidos.", "Instituidor assina escritura, mas recusa transferir o imóvel; o juiz determina o registro em nome da fundação.", "O registro judicial não é mera faculdade: é a consequência prevista para o descumprimento da transferência.", "mandado judicial", "ordem do juiz dirigida ao registro competente"),
"65": ("Os encarregados formulam prontamente o estatuto, submetem-no à autoridade competente e podem recorrer ao juiz; na omissão, o Ministério Público assume a tarefa.", "A fundação não pode ficar sem organização: vale o prazo fixado pelo instituidor ou, se ele nada determinou, cento e oitenta dias.", "Testamenteiro deixa passar cento e oitenta dias sem prazo especial, e o Ministério Público prepara o estatuto.", "Elaboração, aprovação administrativa e eventual recurso judicial são etapas distintas do procedimento.", "incumbência", "encargo formal atribuído a alguém para realizar determinada tarefa"),
"66": ("O Ministério Público do Estado onde a fundação se situa exerce o velamento; no Distrito Federal ou Território atua o respectivo órgão, e atividades em vários Estados atraem atuação em cada um.", "A supervisão acompanha finalidade, patrimônio e regularidade da entidade sem converter o órgão em administrador cotidiano.", "Fundação que atua em dois estados fica sujeita ao velamento do Ministério Público de cada um nesses âmbitos.", "O artigo não cria categoria de fiscalização para fundações federais; distribui o encargo territorialmente.", "velamento", "fiscalização jurídica exercida sobre a fundação e sua finalidade"),
"67": ("A reforma do estatuto exige voto de dois terços dos gestores, preservação da finalidade fundacional e aprovação do Ministério Público em até quarenta e cinco dias, com possível suprimento judicial.", "A entidade pode se adaptar, mas não abandonar o propósito definido por seu instituidor; silêncio ou negativa do órgão fiscalizador permite requerimento ao juiz.", "Conselho aprova mudança administrativa por dois terços e a submete ao Ministério Público dentro do procedimento legal.", "Quórum, finalidade e controle são requisitos cumulativos, e o prazo de quarenta e cinco dias integra a redação vigente.", "finalidade fundacional", "objetivo permanente ao qual o patrimônio da fundação está vinculado"),
"68": ("Sem unanimidade, os administradores pedem ao Ministério Público, ao submeter a reforma, que dê ciência à minoria vencida para impugnação em dez dias.", "A comunicação pelo órgão fiscalizador protege participantes discordantes e permite controle tempestivo da reforma estatutária.", "O Ministério Público cientifica conselheiros vencidos, que questionam mudança contrária à finalidade no prazo legal.", "Os administradores requerem a comunicação; não substituem o Ministério Público no ato de dar ciência.", "minoria vencida", "integrantes que votaram contra a deliberação aprovada"),
"69": ("Ministério Público ou interessado pode promover a extinção se a finalidade se tornar ilícita, impossível ou inútil, ou se vencer o prazo da fundação.", "Salvo disposição contrária no ato constitutivo ou estatuto, o patrimônio vai a fundação de fim igual ou semelhante designada pelo juiz.", "Fundação perde definitivamente a possibilidade de cumprir seu objetivo e o Ministério Público promove sua extinção e destinação patrimonial.", "Inutilidade ou impossibilidade não se presume; causa, legitimidade, ato constitutivo e escolha judicial da destinatária precisam ser examinados.", "extinção", "encerramento jurídico da entidade após verificação da causa legal"),
"70": ("O domicílio da pessoa natural é onde estabelece residência com intenção de permanência.", "A combinação de presença e propósito de fixação define o centro jurídico usado para diversos efeitos.", "Pessoa muda de cidade, aluga moradia estável e transfere para lá sua vida habitual.", "Residência ocasional não cria necessariamente domicílio; fatos concretos revelam a intenção.", "domicílio", "local juridicamente considerado como sede da pessoa"),
"71": ("Quem vive alternadamente em mais de uma residência pode ter qualquer delas como domicílio.", "A pluralidade residencial permite mais de um centro jurídico, sem exigir exclusividade física.", "Pessoa divide o ano regularmente entre duas cidades e pode ser localizada juridicamente em ambas.", "Estadas esporádicas não bastam; deve existir residência habitual alternada.", "pluralidade de domicílios", "existência simultânea de mais de um local juridicamente domiciliar"),
"72": ("Para relações profissionais, também é domicílio o lugar onde a profissão é exercida, inclusive cada estabelecimento ligado à relação.", "O domicílio profissional facilita vincular obrigações ao local efetivo da atividade.", "Médico com clínicas em duas cidades responde por contrato de uma unidade no local correspondente.", "A regra é funcional e não substitui necessariamente o domicílio geral da pessoa.", "domicílio profissional", "local da atividade considerado sede para relações dela decorrentes"),
"73": ("Pessoa sem residência habitual tem domicílio no lugar onde for encontrada.", "Esse domicílio aparente evita ausência de referência jurídica para quem vive de modo itinerante ou sem moradia fixa.", "Viajante permanente é citado no local em que é efetivamente localizado.", "O dispositivo só atua quando não há residência habitual demonstrável.", "domicílio aparente", "local de encontro usado pela lei na falta de residência habitual"),
"74": ("A mudança de domicílio ocorre com transferência de residência e intenção manifesta, inferida também de declarações e circunstâncias.", "O deslocamento físico precisa vir acompanhado de ânimo definitivo, isto é, propósito de estabelecer novo centro de vida.", "Pessoa comunica órgãos locais e instala definitivamente família e bens em outra cidade.", "Uma viagem prolongada ou endereço meramente formal pode não caracterizar mudança.", "ânimo definitivo", "intenção de fixar residência de maneira estável"),
"75": ("União, Estados, Territórios e Municípios têm domicílios legais; demais entidades usam o local da administração ou o domicílio escolhido no ato constitutivo.", "Cada estabelecimento vale como domicílio para seus próprios atos. Se a direção estiver no exterior, vale a agência brasileira ligada à obrigação, não um local estrangeiro livremente escolhido.", "Contrato firmado por uma filial é tratado no local daquele estabelecimento.", "Domicílio estatutário e regra da administração estrangeira são hipóteses diferentes; é preciso identificar qual unidade praticou o ato.", "sede", "local oficial da administração ou referência principal da entidade"),
"76": ("A lei fixa domicílio necessário para incapazes, servidores públicos, militares, marítimos e pessoas que cumprem pena, cada grupo por critério próprio.", "O incapaz segue representante ou assistente; servidor, função permanente; militar, serviço ou comando; marítimo, matrícula do navio; preso, lugar onde cumpre a sentença.", "O domicílio do incapaz acompanha o de seu representante ou assistente.", "Prisão provisória não está expressa no artigo, que menciona o lugar de cumprimento da sentença.", "domicílio necessário", "local definido diretamente pela lei, sem depender apenas da vontade"),
"77": ("O diplomata brasileiro citado no exterior que alega extraterritorialidade sem indicar domicílio no país pode ser demandado no Distrito Federal ou em seu último domicílio brasileiro.", "A regra evita que a prerrogativa torne impossível localizar referência doméstica para a demanda.", "Diplomata citado no estrangeiro não aponta endereço nacional e a ação é proposta no Distrito Federal.", "A aplicação convive com imunidades e normas internacionais específicas.", "extraterritorialidade", "regime especial ligado ao exercício de função diplomática fora do território"),
"78": ("As partes podem escolher por escrito domicílio para exercer e cumprir direitos e obrigações do contrato.", "O domicílio de eleição organiza comunicações e execução da relação sem necessariamente mudar o domicílio geral.", "Contrato indica endereço específico para notificações e pagamento.", "A cláusula pode sofrer controle em relações protegidas e não afasta competência inderrogável.", "domicílio de eleição", "local escolhido contratualmente para efeitos de determinada obrigação"),
"79": ("Imóveis abrangem o solo e tudo que se incorpora a ele natural ou artificialmente.", "A classificação reúne terreno, construções e incorporações estáveis, influenciando forma de transferência e garantias.", "Casa construída integra juridicamente o terreno como bem imóvel.", "A qualificação de máquinas, materiais e direitos exige conferir artigos seguintes e legislação especial.", "incorporação", "união estável de elemento ao solo ou à construção"),
"80": ("Certos direitos sobre imóveis, suas ações e o direito à sucessão aberta são considerados imóveis para efeitos legais.", "A lei atribui natureza imobiliária a posições jurídicas mesmo sem objeto físico imediato.", "Cessão de direito real sobre terreno observa regime relacionado a imóveis.", "A classificação é legal e não depende da aparência material do direito.", "direito real", "poder jurídico exercido diretamente sobre um bem e oponível a terceiros"),
"81": ("Edificações removidas sem perder unidade e materiais retirados provisoriamente para reemprego continuam imóveis.", "A separação física temporária ou transporte integral não altera a classificação quando preservada a destinação indicada.", "Casa modular é deslocada inteira para outro terreno sem desmontagem destrutiva.", "Se houver perda de unidade ou destinação definitiva diversa, a conclusão pode mudar.", "unidade", "integridade funcional e estrutural do bem considerado como um todo"),
"82": ("Móveis são bens capazes de movimento próprio ou remoção externa sem alteração de substância ou destinação econômico-social.", "A classificação alcança o semovente, como um animal, e objetos transportáveis quando a mudança não destrói sua identidade útil.", "Um veículo é removido para outra cidade e permanece o mesmo bem.", "Bens ligados ao solo podem receber tratamento diferente se a retirada os descaracterizar.", "semovente", "bem que se move por força própria, como um animal"),
"83": ("Energias com valor econômico, direitos reais sobre móveis, direitos pessoais patrimoniais e as ações correspondentes são móveis por determinação legal.", "A categoria inclui valores imateriais, direitos e pretensões judiciais que a lei equipara a bens móveis.", "Crédito contratual e a ação destinada a cobrá-lo integram o patrimônio mobiliário do credor.", "A equiparação é legal; a natureza do objeto e regras especiais ainda podem afetar forma e circulação.", "bem móvel por determinação legal", "posição tratada como móvel porque a lei assim estabelece"),
"84": ("Materiais destinados a construção permanecem móveis antes do emprego, e os vindos de demolição voltam a ser móveis.", "A destinação futura ou origem imobiliária não basta; importa a incorporação atual ao solo.", "Tijolos armazenados no canteiro ainda são bens móveis.", "Materiais apenas separados para reemprego imediato podem receber tratamento do artigo 81.", "emprego na construção", "incorporação efetiva do material à obra"),
"85": ("Um bem móvel é fungível quando outro equivalente pode ocupar seu lugar sem alterar a prestação.", "O interesse recai no gênero e na medida, não na individualidade específica do objeto.", "Quem recebe cem unidades padronizadas pode devolver outras equivalentes.", "Objeto usualmente fungível pode tornar-se individualizado por acordo ou circunstância.", "fungível", "bem substituível por equivalente do mesmo gênero e padrão"),
"86": ("Consumíveis são móveis cujo uso destrói imediatamente a substância e também os destinados à alienação.", "Consumo pode ser físico, como alimento, ou jurídico-econômico, como mercadoria de estoque.", "Produto colocado à venda é consumível para o comerciante mesmo antes de ser usado pelo comprador.", "A classificação depende da função concreta do bem na relação examinada.", "consumível", "bem destruído pelo uso ou destinado a ser transferido"),
"87": ("Bens divisíveis podem ser fracionados sem alterar substância, reduzir muito o valor ou prejudicar o uso.", "A divisibilidade jurídica exige que cada parte conserve utilidade e proporção econômica aceitáveis.", "Grande lote de mercadoria homogênea é separado em porções úteis.", "Possibilidade física de cortar não basta se houver perda relevante de valor ou função.", "divisibilidade", "aptidão do bem para fracionamento útil e economicamente razoável"),
"88": ("Bem naturalmente divisível pode tornar-se indivisível por lei ou vontade das partes.", "A indivisibilidade convencional nasce do acordo que preserva tratamento unitário; a lei também pode impor indivisibilidade.", "Coproprietários pactuam manter conjunto produtivo sem fracionamento durante período válido.", "A convenção não pode contrariar limites legais nem prejudicar terceiros de forma ilícita.", "indivisibilidade convencional", "tratamento unitário de bem divisível estabelecido por acordo"),
"89": ("Bens singulares são considerados individualmente, embora possam estar reunidos com outros.", "Cada item mantém identidade jurídica própria dentro de conjunto físico ou econômico.", "Um livro específico continua singular mesmo pertencendo a uma biblioteca.", "A análise pode coexistir com universalidade formada pelo conjunto.", "bem singular", "objeto juridicamente individualizado em relação aos demais"),
"90": ("Universalidade de fato é o conjunto de bens singulares da mesma pessoa com destinação unitária, admitindo relações sobre itens individuais.", "O agrupamento recebe tratamento conjunto sem apagar a autonomia de cada componente.", "Rebanho pertence a um criador e é administrado como unidade econômica.", "Destinação comum e titularidade são essenciais; cada bem ainda pode ser negociado separadamente.", "universalidade de fato", "conjunto material de bens reunidos por destinação comum"),
"91": ("Universalidade de direito é o complexo de relações jurídicas economicamente apreciáveis de uma pessoa.", "O conjunto reúne posições ativas e passivas reconhecidas como unidade pelo ordenamento.", "Herança é tratada como acervo unitário antes da partilha.", "Não se confunde com simples reunião física de objetos.", "universalidade de direito", "conjunto jurídico unitário de direitos e obrigações patrimoniais"),
"92": ("Principal é o bem que existe por si; acessório depende do principal.", "A relação ajuda a determinar destino, regime e interpretação de bens vinculados.", "Edificação pode ser tratada em relação ao terreno conforme as regras aplicáveis.", "A máxima de que o acessório segue o principal possui exceções legais e negociais.", "bem acessório", "bem cuja função ou existência jurídica se vincula a outro principal"),
"93": ("Pertenças são bens destinados de modo duradouro ao uso, serviço ou embelezamento de outro, sem serem parte integrante.", "Existe vínculo funcional estável, mas a pertença conserva autonomia física e jurídica.", "Máquina removível é destinada permanentemente ao serviço de estabelecimento.", "Uso ocasional ou simples proximidade não cria pertença.", "pertença", "bem autônomo destinado duradouramente a servir outro"),
"94": ("Negócios relativos ao bem principal não abrangem pertenças, salvo lei, vontade ou circunstâncias em contrário.", "A transferência do principal não leva, por esse único fato, todo bem funcionalmente associado.", "Venda de imóvel não inclui equipamento autônomo se nada indicar sua inclusão.", "Contrato e contexto podem inverter a regra, por isso é decisivo descrever quais pertenças estão incluídas.", "pertença", "bem autônomo destinado de modo duradouro a servir outro"),
"95": ("A contratação pode alcançar frutos e produtos ainda ligados ao bem que os origina.", "A lei permite contratar resultados futuros identificáveis sem aguardar colheita ou extração.", "Produtor vende antecipadamente safra ainda ligada à plantação.", "Existência futura, riscos e limites ambientais ou contratuais precisam ser definidos.", "frutos e produtos", "utilidades produzidas ou extraídas de um bem principal"),
"96": ("Benfeitorias são voluptuárias quando servem ao deleite ou recreio, úteis quando aumentam ou facilitam o uso e necessárias quando conservam o bem ou evitam deterioração.", "A classificação depende da finalidade concreta da intervenção e influencia direitos de indenização e retenção em outras relações jurídicas.", "Reparo contra infiltração é necessário; ampliação funcional pode ser útil; jardim ornamental destinado ao recreio pode ser voluptuário.", "Valor elevado não torna a obra voluptuária por si só; custo e aparência não substituem a finalidade definida nos parágrafos.", "benfeitoria", "intervenção realizada para conservar, melhorar ou proporcionar deleite em um bem"),
"97": ("Melhoramentos que surgem sem intervenção do proprietário, possuidor ou detentor não são benfeitorias.", "A categoria pressupõe ação humana ligada à relação com o bem; acréscimos naturais seguem outro regime.", "Valorização espontânea do terreno por fenômeno natural não é benfeitoria.", "A origem do melhoramento deve ser identificada antes de aplicar regras de indenização.", "melhoramento", "aumento de utilidade ou valor do bem"),
"98": ("Bens públicos pertencem às pessoas jurídicas de direito público interno; os demais são particulares.", "A titularidade pública determina regime especial de uso, alienação e proteção.", "Praça municipal é bem público, enquanto terreno de empresa privada é particular.", "Bens de entidade estatal de direito privado podem exigir análise específica.", "bem público", "bem pertencente a pessoa jurídica de direito público interno"),
"99": ("Bens públicos dividem-se em uso comum do povo, uso especial e dominicais, conforme destinação e integração patrimonial.", "A classificação distingue bens abertos à coletividade, bens afetados a serviço ou estabelecimento e patrimônio disponível; salvo lei contrária, bens de pessoa pública com estrutura privada são dominicais.", "Rua é de uso comum; prédio de escola é de uso especial; terreno desafetado pode ser dominical.", "A categoria pode mudar por afetação ou desafetação válida, e o parágrafo único contém regra legal própria.", "dominical", "bem público integrante do patrimônio disponível, sem destinação pública específica"),
"100": ("Bens públicos de uso comum e de uso especial são inalienáveis enquanto conservarem essa qualificação.", "A destinação pública impede venda até que procedimento legítimo retire ou altere a afetação.", "Prédio escolar em funcionamento não pode ser alienado como simples patrimônio disponível.", "Desafetação e autorização não são presumidas e devem cumprir o direito público.", "inalienável", "bem que não pode ser transferido enquanto persistir a condição legal"),
"101": ("Bens públicos dominicais têm alienabilidade condicionada ao cumprimento das exigências legais.", "A disponibilidade não significa venda livre; competência, avaliação, autorização e procedimento continuam necessários.", "Município vende terreno desafetado depois de cumprir as etapas administrativas aplicáveis.", "O Código Civil não substitui licitação e demais normas de direito público.", "alienabilidade condicionada", "possibilidade de transferência dependente do cumprimento de requisitos"),
"102": ("Bens públicos não podem ser adquiridos por usucapião.", "A posse prolongada de particular não transforma, por decurso do tempo, bem público em propriedade privada.", "Ocupante de área municipal por décadas não obtém domínio por usucapião.", "Classificar corretamente o titular do bem é decisivo; outras formas legais de regularização são tema distinto.", "usucapião", "aquisição de propriedade pela posse qualificada durante prazo legal"),
"103": ("O uso comum de bens públicos pode ser gratuito ou remunerado conforme decisão legal da entidade administradora.", "Cobrança compatível com a finalidade não retira necessariamente o caráter comum do uso.", "Lei autoriza pedágio pelo uso de determinada rodovia pública, sem retirar seu caráter de bem de uso comum.", "Preço, taxa, igualdade de acesso e competência dependem do regime administrativo aplicável.", "uso comum", "utilização de bem público acessível à coletividade segundo regras gerais"),
"104": ("A validade do negócio jurídico exige agente capaz, objeto lícito, possível e determinado ou determinável, além de forma admitida.", "Os requisitos controlam quem manifesta vontade, sobre o que se negocia e como o ato deve ser exteriorizado.", "Compra por pessoa capaz, de bem permitido e identificado, segue forma não proibida.", "Validade não garante ausência de todos os defeitos; vícios de vontade e regras especiais também devem ser examinados.", "negócio jurídico", "manifestação de vontade destinada a produzir efeitos reconhecidos pelo direito"),
"105": ("O contratante capaz não pode usar a incapacidade relativa do outro para obter vantagem, nem a proteção favorece, em regra, demais interessados capazes.", "A proteção pertence ao relativamente incapaz, mas pode alcançar cointeressados quando a prestação ou o direito compartilhado não admitir divisão.", "Contratante capaz não anula sua obrigação apenas porque o outro tinha dezessete anos, salvo reflexo necessário de objeto comum indivisível.", "A exceção depende de indivisibilidade jurídica; mera conveniência de julgamento conjunto não basta.", "benefício próprio", "vantagem buscada por quem não é o destinatário da proteção legal"),
"106": ("Um obstáculo existente no início não invalida o negócio quando for superável ou desaparecer antes do evento condicionado.", "A lei preserva atos cuja prestação ainda pode ser cumprida por alguém ou se tornar possível no momento relevante.", "Contrato condicionado a autorização futura permanece viável se ela é obtida antes do evento.", "Impossibilidade total e definitiva recebe tratamento diferente; o momento contratual importa.", "impossibilidade relativa", "obstáculo que não impede todas as pessoas ou pode ser superado"),
"107": ("A declaração de vontade não depende de forma especial, salvo quando a lei a exigir expressamente.", "Predomina liberdade de forma: fala, escrita ou conduta podem bastar, desde que não exista solenidade obrigatória.", "Acordo simples é celebrado por mensagem quando não há solenidade específica na norma aplicável.", "Prova e validade são questões diferentes; forma livre pode ser difícil de demonstrar.", "liberdade de forma", "possibilidade de manifestar vontade por meio não previamente imposto"),
"108": ("Salvo regra legal diferente, negócios sobre direitos reais imobiliários acima do equivalente a trinta unidades do maior salário mínimo nacional exigem escritura pública.", "A solenidade alcança constituição, transferência, modificação e renúncia desses direitos e integra a validade do negócio.", "Compra de imóvel acima do patamar legal é formalizada em tabelionato antes do registro.", "O valor deve superar esse patamar de trinta salários mínimos, e leis especiais podem estabelecer exceções.", "escritura pública", "instrumento solene lavrado por tabelião com fé pública"),
"109": ("Se as partes estipulam que o negócio só vale por instrumento público, essa forma torna-se essencial.", "A vontade contratual pode elevar a solenidade a requisito de validade, mesmo quando a lei não a imporia.", "Partes condicionam doação à escritura e o simples documento particular não conclui o negócio.", "É preciso distinguir exigência constitutiva de promessa de documentar ato já perfeito.", "substância do ato", "requisito indispensável à própria formação válida do negócio"),
"110": ("A manifestação continua válida apesar de reserva mental do declarante, salvo se o destinatário conhecia a intenção oculta.", "A confiança na declaração externa é protegida quando a outra parte desconhece a divergência entre vontade interna e declaração.", "Pessoa declara vender um bem, mas secretamente não quer produzir a venda; se o comprador ignora a reserva, a manifestação subsiste.", "Reserva mental existe na formação da declaração e não se confunde com simples intenção posterior de descumprir.", "reserva mental", "divergência secreta entre vontade interna e declaração exterior"),
"111": ("O silêncio pode valer como concordância quando circunstâncias ou usos autorizarem e não for necessária declaração expressa.", "Não existe regra geral de que calar é consentir; o significado nasce da relação, prática ou norma aplicável.", "Em relação continuada, prática aceita pode atribuir efeito à falta de recusa dentro do prazo.", "Silêncio imposto unilateralmente ou em contexto vulnerável não deve ser tratado, sem outros elementos, como aceitação.", "anuência", "concordância juridicamente relevante com ato ou proposta"),
"112": ("Na interpretação da declaração, deve prevalecer a intenção nela revelada sobre o sentido puramente literal das palavras.", "O intérprete busca o propósito objetivamente manifestado no contexto, sem depender apenas de leitura gramatical isolada.", "Cláusula mal redigida é compreendida conforme objetivo comum demonstrado pelas negociações.", "Intenção secreta não comprovada não substitui a confiança legítima criada pela declaração.", "interpretação", "processo de determinar o sentido e alcance de uma manifestação jurídica"),
"113": ("Negócios são interpretados conforme boa-fé e usos, considerando conduta posterior, práticas de mercado, benefício de quem não redigiu a cláusula e negociação razoável inferida do contexto.", "As partes podem pactuar regras de interpretação, integração e preenchimento de lacunas diferentes das regras legais disponíveis.", "Cláusula ambígua é entendida de modo coerente com a prática posterior das próprias partes.", "O artigo não menciona alocação de riscos; seus critérios atuais foram ampliados pela Lei da Liberdade Econômica.", "boa-fé", "padrão de lealdade, coerência e proteção da confiança nas relações jurídicas"),
"114": ("Negócios benéficos e renúncias devem ser interpretados estritamente.", "Não se ampliam por analogia ou presunção vantagens gratuitas nem abandono de direitos além do que foi claramente manifestado.", "Perdão de uma parcela da dívida não se estende, por esse único fato, às demais.", "Interpretação estrita não autoriza ignorar contexto, validade ou boa-fé; apenas limita expansão indevida.", "renúncia", "abandono voluntário de direito disponível de modo juridicamente válido"),
}

